const byId=new Map(CONTROL_DOMAINS.map(d=>[d.id,d]));
const architectures=new Map(CONTROL_ARCHITECTURES.map(a=>[a.id,a]));
const scenarioIds=new Set(CONTROL_SCENARIOS.map(s=>s.id));
export const connectionModesFor=id=>byId.get(id)?.request?['absent','monitor','supervisory']:['absent','monitor'];
export function normalizeControlState(input={}){
  const domain=byId.has(input.domain)?input.domain:'traction';
  const architecture=architectures.has(input.architecture)?input.architecture:'summaries';
  const connections={};
  if(input.connections&&typeof input.connections==='object'&&!Array.isArray(input.connections))for(const [id,mode] of Object.entries(input.connections))if(byId.has(id)&&connectionModesFor(id).includes(mode))connections[id]=mode;
  return {domain,architecture,connections,scenario:scenarioIds.has(input.scenario)?input.scenario:'normal',trace:input.trace==='request'?'request':'indication',step:Math.min(4,Math.max(0,Math.floor(Number(input.step)||0)))};
}
export function connectionFor(input,id){
  const state=normalizeControlState(input),domain=byId.get(id||state.domain);
  if(state.connections[domain.id])return state.connections[domain.id];
  const mode=architectures.get(state.architecture).defaultMode;
  return mode==='supervisory'&&!domain.request?'monitor':mode;
}

export function evaluateControlInterface(input={}){
  const state=normalizeControlState(input),domain=byId.get(state.domain),mode=connectionFor(state),lost=state.scenario==='link-loss',local=state.scenario==='local-mode',missing=state.scenario==='feedback-missing';
  const canRequest=mode==='supervisory'&&!!domain.request;
  let steps;
  if(state.trace==='request')steps=[
    {label:'Request origin',actor:'common',text:!canRequest?(mode==='absent'?'No common-display interface is included. There is no common-display command path.':'This common-display interface carries monitoring only. It has no control output.'):`${domain.request} originates at the configured common interface.`},
    {label:'Transport',actor:'transport',text:!canRequest?'No request is sent on a monitoring-only or absent interface.':lost?'The supervisory link is unavailable. Delivery cannot be established.':'The defined application interface carries a request; the network does not decide its authority.'},
    {label:'Local decision',actor:'local',text:!canRequest||lost?'No local action is inferred from this common interface.':local?'In this selected case, local control is selected and the remote request is rejected.':domain.localAction},
    {label:'Outcome evidence',actor:'field',text:!canRequest||lost||local?'The field condition is not changed or inferred by the teaching trace.':missing?'Feedback is unavailable. A received or accepted request does not establish the result.':domain.feedback},
    {label:'Operator conclusion',actor:'common',text:!canRequest?'Monitoring capability does not grant a control capability.':lost?'Request delivery and present field state are unconfirmed.':local?'Rejected remote request; status monitoring can continue.':missing?'Accepted does not mean completed: show an unconfirmed outcome, not a successful equipment state.':'Only the defined, separately returned evidence can support the displayed outcome; this trace performs no equipment action.'},
  ];
  else steps=[
    {label:'Field observation',actor:'field',text:`${domain.examplePoint}: ${domain.pointType.toLowerCase()}. The point describes its source, not the entire subsystem.`},
    {label:'Local acquisition',actor:'local',text:'The source interface supplies value/state, point identity, quality and the applicable timestamp. A summary point can hide detail; its definition matters.'},
    {label:'Transport',actor:'transport',text:lost?'The supervisory link is unavailable. Do not refresh a last-known value as if it were a current observation.':'Configured transport carries the application data. A link-up indication alone does not prove a fresh, valid point.'},
    {label:'Native supervision',actor:'native',text:lost?'The native supervisory application lacks fresh data from this path.':missing?'The selected feedback point is unavailable even though communication can be present.':`${domain.supervisor} presents the received state with its quality and age.`},
    {label:'Common station view',actor:'common',text:mode==='absent'?'No common station interface is included. Information remains with the native application or local equipment.':lost||missing?'Show unavailable/stale or unconfirmed information, not a fresh normal state.':'Only the points selected in the integration contract are forwarded. The common display does not acquire every internal measurement.'},
  ];
  return {state,domain,mode,canRequest,architecture:architectures.get(state.architecture),scenario:CONTROL_SCENARIOS.find(s=>s.id===state.scenario),steps,active:steps[state.step],remoteQuality:lost?'Unavailable — last value is not current':missing?'Selected feedback unavailable':'Received information; quality still matters',commandState:!canRequest?'No common-display command interface':lost?'Delivery unavailable':local?'Rejected in selected local mode':missing?'Outcome unconfirmed':'Permitted interface; outcome requires feedback',localState:lost?domain.loss:domain.localAction,interfaces:CROSS_SYSTEM_INTERFACES.filter(e=>e.from===domain.id||e.to===domain.id)};
}

export function getInterfaceContext(conceptId,viewId,variantId){
  // A selected component is stronger evidence than the page from which the
  // learner followed a cross-system link. Do not inherit its previous owner.
  const domain=CONTROL_DOMAINS.find(d=>d.components.includes(conceptId));
  if(domain)return {domain:domain.id};
  if(viewId==='station-networks')return {domain:variantId==='building'?'building':variantId==='power'?'traction':'building'};
  if(viewId==='tunnel-ventilation')return {domain:'tunnel'};
  if(viewId==='fire-systems')return {domain:'fire'};
  if(/^communications-network/.test(viewId||''))return {domain:'network'};
  if(viewId==='communications-telephony'&&variantId==='operational-radio')return {domain:'radio'};
  if(/^communications-passenger|communications-telephony/.test(viewId||''))return {domain:'passenger'};
  if(/^communications-video|communications-security/.test(viewId||''))return {domain:'security'};
  return {domain:'traction'};
}

const concept=(id,label,summary,details,sources,related)=>({id,label,summary,details,sources,related,caveat:'An original functional teaching model. The example does not specify an installed architecture, safety classification, priority matrix or operating procedure.'});
export const CONTROL_INTERFACE_CONCEPTS = [
  concept('control-responsibilities','Control responsibilities and optional interfaces','Separate the physical equipment, local logic, supervisory applications, communications and people.', ['Power SCADA, BAS/BMS, tunnel ventilation and station smoke controls have different responsibilities even when products or operator displays are integrated.','The Interfaces explorer compares absent integration, status sharing and selected supervisory requests. Each connection names what crosses it and what remains with the originating function.'],['CI01','CI02','CI03','CI04','F03'],['power-scada','bas-controller','tvcs-controller','station-smoke-controller','interface-contract']),
  concept('tvcs-controller','Tunnel ventilation control system · TVCS / VCS','Coordinate the selected tunnel ventilation equipment and its engineered control strategy.', ['A ventilation control system can include distributed controllers, motor-control interfaces and its own SCADA/HMI software. It can exchange information with wider railway SCADA without transferring its plant-control responsibility.','Normal and emergency duties, train-system interfaces, local controls and command priorities are allocated by the particular railway. The examples compare functional boundaries; they do not provide a ventilation response sequence.'],['CI02','CI03','CI04'],['tunnel-fan','tunnel-damper','tunnel-shaft','station-smoke-controller','station-scada']),
  concept('station-smoke-controller','Station smoke-system control','Coordinate station smoke extraction, pressurisation or air-release equipment as allocated by the design.', ['These functions may have dedicated fire inputs, process control and motor control. Their relationship to tunnel ventilation and comfort HVAC needs an explicit interface definition.','A common supervisory display is separate from the local control sequence and any emergency/manual control hierarchy.'],['CI01','CI05'],['fire-panel','tvcs-controller','bas-controller','smoke-control']),
  concept('local-plant-controller','Local plant control and acquisition','Local logic and I/O connect physical equipment with the permitted supervisory interface.', ['A PLC can execute control logic; an RTU can acquire points and expose remote interfaces. Products can combine these capabilities, but a box labelled PLC/RTU does not define who owns a control duty.','A requested action, controller acceptance, output state, field movement and returned indication are different observations. Select a concrete subsystem in Interfaces to see the boundary.'],['CM01','CM02','CI05'],['scada-rtu','scada-input-module','scada-output-module','interface-contract']),
  concept('interface-contract','Interface identity, direction and authority','Define what is exchanged, how it is interpreted and which function can act on it.', ['A useful interface description states endpoints, direction, meaning, units, quality, time basis, permitted requests and feedback. The transport technology is a separate question.','No connection, a monitoring-only connection and an authorized control interface are all possible allocations. Not displaying an interface is not permission to remove a required function from an engineered railway.'],['CM01','CI06','CI08','CI09'],['control-responsibilities','scada-information-quality','network-management']),
  concept('network-management','Network transport and network management','The communications system carries application traffic and provides its own infrastructure diagnostics.', ['Fibre and switching support communications transport. Network management observes devices and links; SCADA consumes plant/application points. They are distinct even when a network alarm is passed to a common display.','A connected cable, network link-up state or protocol name proves neither plant command authority nor current application data.'],['CI11','CM04','F20'],['network-switch','communications-router','fiber-backbone','interface-contract']),
  concept('drainage-controller','Drainage level and pump control','Use local level information and equipment state to control selected pumps.', ['Level control, motor protection and optional supervisory integration are separable. An example pump controller can report to BAS, facility SCADA or its own local interface.','A run indication does not establish outfall capacity or prove successful drainage; water level and other physical evidence remain relevant.'],['CI10','CI06'],['route-drainage','depot-drainage','bas-controller','interface-contract']),
];

export function applyControlInterfacesCatalog(sources,concepts){
  sources.push(...CONTROL_INTERFACE_SOURCES);
  concepts.push(...CONTROL_INTERFACE_CONCEPTS);
  const changes={
    'station-scada':{label:'Facility / station SCADA',summary:'Present selected subsystem information and explicitly permitted supervisory requests.',details:['Facility SCADA is an application scope, not a universal owner of station plant. A railway can provide no integration, monitoring-only summaries, or selected control requests for each subsystem.','BAS, TVCS, fire systems, power supervision, signalling, passenger services and network management retain their defined responsibilities. A shared HMI does not make their interfaces identical.','Use Interfaces to compare the point origin, common-display data, request permission and independent feedback for each function.'],sources:['F03','CI01','CI03','CI04'],related:['power-scada','bas-controller','tvcs-controller','station-smoke-controller','interface-contract','network-management']},
    'bas-controller':{summary:'Control building-service plant through local loops, schedules and configured interfaces.',details:['BAS/BMS has its own controllers, field I/O and supervisory functions. A common station display may receive selected BAS points without running those loops.','The boundary varies by railway. The Crossrail HVAC narrative distinguishes BMS building services from life-safety ventilation; other published projects use different ECS/BMS scopes. Neither the name BMS nor a shared network determines safety responsibilities.'],sources:['F15','CI01','CI03','CI04'],related:['bas-sensor','bas-actuator','plant-network','station-scada','tvcs-controller','control-responsibilities']},
    'scada-rtu':{label:'Field acquisition and supervisory interface · PLC / RTU',related:['scada-input-module','scada-output-module','scada-gateway','local-plant-controller','interface-contract']},
  };
  for(const [id,patch] of Object.entries(changes)){const item=concepts.find(c=>c.id===id);if(item)Object.assign(item,patch);}
}
